def calculate_b_ik_m_i(B_i, k, C_i, F_i, higher_priority_tasks, phi_j_map):
    # Effective computation for the part of job k before its final subjob
    C_prime = (k + 1) * C_i - F_i

    x_current = B_i + C_prime
    x_next = 0
    while True:
        x_next = B_i + C_prime
        for hp_task_j in higher_priority_tasks:
            phi_j = phi_j_map.get(hp_task_j.id, 0)
            num_jobs = max(0, math.ceil((x_current - phi_j) / hp_task_j.T))
            x_next += num_jobs * hp_task_j.C
        if x_next == x_current:
            return x_current
        x_current = x_next

def calculate_r_ik(B_i, k, C_i, F_i, T_i, phi_i, higher_priority_tasks, phi_j_map):
    b_ik_m_i = calculate_b_ik_m_i(B_i, k, C_i, F_i, higher_priority_tasks, phi_j_map)
    return b_ik_m_i + F_i - (k * T_i + phi_i)

