import math

def calculate_wl_D_i(WL_D_i, T_i):
    return math.ceil(WL_D_i / T_i)

def calculate_WR_D_ik(task_i, k, B_D_i, F_i, T_i, n, WR_P_i_func, WO_P_n_func):
    if task_i.priority_level < n:
        # For tasks that can be blocked
        C_effective = B_D_i + (k + 1) * task_i.C - F_i
        return WR_P_i_func(C_effective) + F_i - k * T_i
    else: # task_i is the lowest priority task (i == n)
        # For the lowest priority task, which cannot be blocked
        C_effective = (k + 1) * task_i.C - F_i
        return WO_P_n_func(C_effective) + F_i - k * T_i

def calculate_WR_D_i_from_jobs(task_i, wl_D_i, calculate_WR_D_ik_func):
    max_WR_D_i = 0
    for k in range(wl_D_i):
        current_WR_D_ik = calculate_WR_D_ik_func(task_i, k)
        if current_WR_D_ik > max_WR_D_i:
            max_WR_D_i = current_WR_D_ik
    return max_WR_D_i

def calculate_WL_D_i_alternative(task_i, B_D_i, WR_P_i_func):
    k = 0
    while True:
        C_total = B_D_i + (k + 1) * task_i.C
        response_time_for_total_C = WR_P_i_func(C_total)
        if response_time_for_total_C <= (k + 1) * task_i.T:
            return response_time_for_total_C
        k += 1

def check_active_period_termination(task_i, B_D_i, WR_P_i_func):
    k = 0
    while True:
        total_computation_demand = B_D_i + (k + 1) * task_i.C
        response_time_for_demand = WR_P_i_func(total_computation_demand)
        if response_time_for_demand <= (k + 1) * task_i.T:
            return k # The active period is over after job k
        k += 1

def calculate_WR_D_i_iterative(task_i, D_i, B_D_i, C_i, T_i, WR_P_i_func, calculate_WR_D_ik_func):
    max_WR_D_i = calculate_WR_D_ik_func(task_i, 0) # WR_D_i_0

    if max_WR_D_i > D_i:
        return max_WR_D_i # Task 0 already misses deadline

    k = 0
    while True:
        # Check termination condition (active period over)
        termination_check_C = B_D_i + (k + 1) * C_i
        if WR_P_i_func(termination_check_C) <= (k + 1) * T_i:
            return max_WR_D_i # Active period is over

        k += 1
        current_WR_D_ik = calculate_WR_D_ik_func(task_i, k)

        if current_WR_D_ik > D_i:
            return current_WR_D_ik # Task k misses deadline

        max_WR_D_i = max(max_WR_D_i, current_WR_D_ik)

def calculate_WR_D_ik_pessimistic_WO(task_i, k, B_D_i, F_i, T_i, WO_P_i_func):
    C_effective = B_D_i + (k + 1) * task_i.C - F_i
    return WO_P_i_func(C_effective) + F_i - k * T_i

def calculate_WR_D_ik_pessimistic_WR(task_i, k, B_D_i, F_i, delta, T_i, WR_P_i_func):
    C_effective = B_D_i + (k + 1) * task_i.C - (F_i - delta)
    return WR_P_i_func(C_effective) + (F_i - delta) - k * T_i

